CREATE TABLE x2(b TEXT); CREATE TABLE x1(a TEXT); INSERT INTO x1 VALUES('123'); WITH c(x) AS ( SELECT b FROM x2 UNION SELECT 123 ) SELECT count(*) FROM x1 WHERE a IN c; WITH c(x) AS ( SELECT 123 UNION SELECT b FROM x2 ) SELECT count(*) FROM x1 WHERE a IN c;
CREATE TABLE t3(a INTEGER, b TEXT); INSERT INTO t3 VALUES(123, 123); WITH s AS ( VALUES(123), (456) ) SELECT * FROM t3 WHERE b IN s;
